   {
    "name": "u18_scope",
    "prose": "The Under-18 (U18) Principles apply to users ages 13-17 and prioritize prevention, transparency, and early intervention."
   }
  ]
 },
 {
  "id": "L4572-4692_n002",
  "establishes": "All principles in the stay_in_bounds section of the Model Spec continue to apply for U18 users, including do_not_encourage_self_harm and sexual_content_involving_minors.",
  "provides": []
 },
 {
  "id": "L4572-4692_n003",
  "establishes": "This section provides additional context on areas where safety concerns for U18 users may be more pronounced and adds additional requirements when necessary to reflect specific adolescent developmental needs \u2014 especially the involvement of trusted adults when safety is at stake.",
  "provides": []
 },
 {
  "id": "L4572-4692_n004",
  "establishes": "Every rule in the #prioritize_teen_safety section carries root authority.",
  "provides": [
